export function responseScene(t:number){const p=responseProgress(t+18),q=routePoint(1-p),branch=E(t,2.3,3.6);return `${heading(t,6,'THE HTTP RESPONSE','The service returns HTML for this page.')}${route(1,true)}${endpoint(380,650,'browser','BROWSER')}${endpoint(1540,650,'server','WEB SERVICE')}${lock(960,495,1)}${appear(mt(1540,432,'200 OK',35,C.amber,'text-anchor="middle"'),t,.35)}<g opacity="${1-E(t,3.5,4)}">${message(q.x,q.y,'HTML',C.amber)}</g>${appear(badge(105,865,'RESPONSE: 200 OK'),t,.25)}${mt(1816,891,'EXAMPLE SUCCESS RESPONSE',20,C.slate,'text-anchor="end"')}<g>${['CSS','JS','IMAGES'].map((s,i)=>{const y=405+i*100;const a=S(t,2.5+i*.35);return `<g opacity="${a}">${line(445,600,640,y,C.blue,2,'stroke-dasharray="7 9"')}${rect(650,y-34,170,64,C.mid,8,`stroke="${C.blue}" stroke-width="1"`)}${mt(735,y+7,s,24,C.white,'text-anchor="middle"')}${line(835,y,1200,y,C.slate,1,'opacity=".4"')}${rect(lerp(835,1170,E(t,2.5+i*.25,3.5+i*.1)),y-4,30,8,C.blue,3,`opacity="${a}"`)}</g>`;}).join('')}${mt(960,790,'HTML REFERENCES RESOURCES → SEPARATE REQUESTS',23,C.slate,`text-anchor="middle" opacity="${branch}"`)}</g>`;}
