import {C,tx} from './design';
import {CAPTIONS,E,camera,clamp,flash} from './motion';
import {storm} from '../scenes/Storm';import {inside} from '../scenes/Inside';import {separation} from '../scenes/Charge';import {field} from '../scenes/Field';import {strike} from '../scenes/Strike';import {thunder} from '../scenes/Thunder';
export function svgAt(time:number){const t=clamp(time,0,29.99999),cam=camera(t);const render=(at:number)=>at<3?storm(at):at<8?inside(at):at<14?separation(at):at<20?field(at):at<26?strike(at):thunder(at);let content=render(t);
 for(const boundary of[3,8,14,20,26])if(t>=boundary-.3&&t<boundary){const q=E(t,boundary-.3,boundary);content=`<g opacity="${1-q}">${content}</g><g opacity="${q}">${render(boundary)}</g>`;}
 const caption=CAPTIONS.find(c=>t*1000>=c.startMs&&t*1000<c.endMs);const subs=caption?`<g data-caption="true"><rect x="80" y="1370" width="860" height="139" rx="16" fill="#050A14" fill-opacity=".82"/>${caption.text.split('\n').map((s,i)=>tx(510,1425+i*47,s,34,C.white,'font-family="Inter,sans-serif" font-weight="500" text-anchor="middle"')).join('')}</g>`:'';
 return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920" viewBox="0 0 1080 1920" font-family="'Space Grotesk',sans-serif" font-weight="700" style="background:${C.navy};display:block"><defs><radialGradient id="cloudLight"><stop stop-color="${C.violet}" stop-opacity=".7"/><stop offset="1" stop-color="${C.navy}" stop-opacity="0"/></radialGradient><radialGradient id="vignette"><stop offset=".3" stop-color="${C.navy}" stop-opacity="0"/><stop offset="1" stop-color="#030713" stop-opacity=".75"/></radialGradient><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5 0 10Z" fill="${C.cyan}"/></marker></defs><rect width="1080" height="1920" fill="${C.navy}"/><g transform="translate(${cam.x} ${cam.y}) translate(540 900) scale(${cam.zoom}) translate(-540 -900)">${content}</g><rect width="1080" height="1920" fill="${C.white}" opacity="${flash(t)*.34}" pointer-events="none"/><rect width="1080" height="1920" fill="url(#vignette)" opacity=".22" pointer-events="none"/>${subs}</svg>`;
}
