import React from 'react';import {ThreeCanvas} from '@remotion/three';import {Audio} from '@remotion/media';import {AbsoluteFill,staticFile,useCurrentFrame,useVideoConfig} from 'remotion';import '@fontsource/space-grotesk/latin-700.css';import '@fontsource/ibm-plex-mono/latin-500.css';import {DownforceWorld} from './Scene';import {DownforceOverlay} from './Overlay';
export const DownforceVisual:React.FC<{t:number}>=({t})=><AbsoluteFill style={{backgroundColor:'#080C12'}}><ThreeCanvas width={1080} height={1920} camera={{fov:38,near:.03,far:180}} gl={{antialias:true,preserveDrawingBuffer:true}} frameloop="demand"><DownforceWorld t={t}/></ThreeCanvas><DownforceOverlay t={t}/></AbsoluteFill>;
export const ScienceOfDownforce:React.FC=()=>{const frame=useCurrentFrame();const{fps}=useVideoConfig();return <><DownforceVisual t={frame/fps}/><Audio src={staticFile('downforce/audio/mix.wav')} premountFor={fps}/></>;};
