import clouds from './clouds.json';
import {E,S,hash} from './motion';
export const C={navy:'#0A1224',slate:'#34435D',violet:'#7567F4',cyan:'#6FDDF4',amber:'#FFBA69',white:'#F7FBFF'};
export const tx=(x:number,y:number,s:string,size=32,fill:string=C.white,extra='')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" ${extra}>${s.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</text>`;
export const mt=(x:number,y:number,s:string,size=22,fill:string=C.cyan,extra='')=>tx(x,y,s,size,fill,`font-family="'IBM Plex Mono',monospace" font-weight="500" letter-spacing="1" ${extra}`);
export const dot=(x:number,y:number,r:number,fill:string=C.cyan,extra='')=>`<circle cx="${x}" cy="${y}" r="${Math.max(0,r)}" fill="${fill}" ${extra}/>`;
export const line=(x:number,y:number,a:number,b:number,fill:string=C.cyan,w=2,extra='')=>`<path d="M${x} ${y}L${a} ${b}" fill="none" stroke="${fill}" stroke-width="${w}" ${extra}/>`;
export const appear=(s:string,t:number,a:number)=>`<g opacity="${S(t,a)}" transform="translate(0 ${(1-S(t,a))*25})">${s}</g>`;
export const headline=(t:number,lines:string[],tag:string)=>`${appear(mt(96,259,tag,22),t,0)}${lines.map((s,i)=>appear(tx(92,354+i*80,s,72,C.white,'letter-spacing="-3"'),t,.05+i*.08)).join('')}`;
export function cloudField(t:number,inside=0,light=0){return `<g>${clouds.map((src,i)=>{const drift=Math.sin(t*.11+i)*16*(i+1);return `<image href="${src}" x="${-180-i*90+drift}" y="${250-i*150-inside*130}" width="${1440+i*180}" height="${1500+i*150}" opacity="${.7-i*.08}"/>`;}).join('')}<ellipse cx="590" cy="750" rx="650" ry="570" fill="url(#cloudLight)" opacity="${.12+light*.6+inside*.08}"/></g>`;}
export function iceShape(x:number,y:number,r:number,rotation:number,graupel=false){return graupel?`<g transform="translate(${x} ${y}) rotate(${rotation})">${dot(0,0,r,'#B1C1D7')}${dot(-r*.3,-r*.3,r*.7,C.white,'opacity=".4"')}${Array.from({length:5},(_,i)=>dot(Math.cos(i*1.25)*r*.7,Math.sin(i*1.25)*r*.7,r*.32,'#D9E5F4')).join('')}</g>`:`<g transform="translate(${x} ${y}) rotate(${rotation})"><path d="M0 ${-r}L${r*.62} ${-r*.32}L${r*.5} ${r*.6}L0 ${r}L${-r*.62} ${r*.4}L${-r*.5} ${-r*.6}Z" fill="${C.white}" fill-opacity=".65" stroke="${C.cyan}" stroke-width="1.5"/>${line(-r*.5,-r*.6,r*.5,r*.6,C.white,1)}${line(0,-r,0,r,C.white,1)}</g>`;}
export function terrain(){return `<path d="M0 1430L110 1395 210 1420 340 1368 460 1410 540 1400 610 1370 730 1415 850 1384 1080 1420V1920H0Z" fill="#080F1E"/><path d="M510 1408V1358h30v50m-36-50 21-18 22 18" fill="#080F1E" stroke="#71809B" stroke-opacity=".3" stroke-width="2"/>`;}
export const charge=(x:number,y:number,positive:boolean,opacity=1)=>`<g opacity="${opacity}">${dot(x,y,17,positive?C.amber:C.violet,'opacity=".18"')}${line(x-7,y,x+7,y,positive?C.amber:C.violet,3)}${positive?line(x,y-7,x,y+7,C.amber,3):''}</g>`;
export function charges(t:number){return `<g>${Array.from({length:24},(_,i)=>{const positive=i<12;const x=190+hash(i+1)*660;const y=(positive?550:930)+hash(i+51)*190;return charge(x,y,positive,E(t,8+i*.025,9.5+i*.025));}).join('')}</g>`;}
