import {E,S,ROUTE_PATH,clamp,lerp,progress} from './motion';
export const C={navy:'#0B1220',mid:'#14243A',blue:'#4D8CFF',cyan:'#5DE1E6',amber:'#FFB45C',white:'#F3F7FB',slate:'#8FA3B8'};
export const mono="'IBM Plex Mono',monospace";
export const esc=(s:string)=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
export const tx=(x:number,y:number,s:string,size=32,fill:string=C.white,extra='')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" ${extra}>${esc(s)}</text>`;
export const mt=(x:number,y:number,s:string,size=22,fill:string=C.slate,extra='')=>tx(x,y,s,size,fill,`font-family="${mono}" font-weight="500" letter-spacing="1" ${extra}`);
export const rect=(x:number,y:number,w:number,h:number,fill:string=C.mid,r=16,extra='')=>`<rect x="${x}" y="${y}" width="${Math.max(0,w)}" height="${Math.max(0,h)}" rx="${r}" fill="${fill}" ${extra}/>`;
export const dot=(x:number,y:number,r:number,fill:string=C.cyan,extra='')=>`<circle cx="${x}" cy="${y}" r="${Math.max(0,r)}" fill="${fill}" ${extra}/>`;
export const line=(x1:number,y1:number,x2:number,y2:number,fill:string=C.slate,width=2,extra='')=>`<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="${fill}" stroke-width="${width}" ${extra}/>`;
export function panel(x:number,y:number,w:number,h:number,content:string,accent:string=C.slate){return rect(x+8,y+14,w,h,'#060B13',18,'opacity=".65"')+rect(x,y,w,h,C.mid,16,`stroke="${accent}" stroke-opacity=".55" stroke-width="1.5"`)+content;}
export const appear=(content:string,t:number,a:number,dy=30)=>`<g opacity="${S(t,a)}" transform="translate(0 ${(1-S(t,a))*dy})">${content}</g>`;
export const badge=(x:number,y:number,label:string,fill:string=C.cyan)=>`${rect(x,y-30,label.length*14+32,44,fill,5)}${mt(x+16,y,label,20,C.navy)}`;
export function heading(t:number,n:number,title:string,sub:string){return `${appear(mt(104,192,'0'+n+' / THE INVISIBLE JOURNEY',21,C.cyan)+tx(100,288,title,76,C.white,'letter-spacing="-3"'),t,0,22)}${appear(tx(104,342,sub,27,C.slate,'font-weight="500"'),t,.12,18)}`;}
export function browser(x:number,y:number,w:number,h:number,inside:string,url='example.com/page'){return `<g>${panel(x,y,w,h,'',C.blue)}${rect(x,y,w,57,'#1B2D45',16)}${rect(x,y+28,w,29,'#1B2D45',0)}${[C.slate,C.slate,C.slate].map((c,i)=>dot(x+26+i*22,y+28,5,c,'opacity=".55"')).join('')}${rect(x+115,y+13,w-145,32,C.navy,7)}${mt(x+134,y+36,url,17,C.slate)}${inside}</g>`;}
export function endpoint(x:number,y:number,type:'browser'|'server',label:string){const icon=type==='browser'?`${rect(x-65,y-50,130,90,C.mid,8,`stroke="${C.blue}" stroke-width="2"`)}${line(x-65,y-25,x+65,y-25,C.blue,2)}${dot(x-51,y-37,3,C.blue)}${line(x-28,y+52,x+28,y+52,C.slate,3)}${line(x,y+41,x,y+51,C.slate,3)}`:`${rect(x-58,y-69,116,138,C.mid,9,`stroke="${C.slate}" stroke-width="2"`)}${[-39,0,39].map(z=>`${rect(x-42,y+z-13,84,26,C.navy,4)}${dot(x+27,y+z,4,C.cyan)}${line(x-28,y+z,x+3,y+z,C.slate,2)}`).join('')}`;return icon+mt(x,y+98,label,21,C.white,'text-anchor="middle"');}
export function route(t:number,secure=true){return `<path d="${ROUTE_PATH}" fill="none" stroke="${C.mid}" stroke-width="18" stroke-linejoin="round"/><path d="${ROUTE_PATH}" fill="none" stroke="${secure?C.cyan:C.blue}" stroke-width="3" pathLength="1" stroke-dasharray="1" stroke-dashoffset="${1-E(t,0,.8)}"/>${[650,790,1110,1270].map((x,i)=>dot(x,i===0||i===3?650:545,5,C.slate)).join('')}`;}
export function message(x:number,y:number,label:string,color:string=C.blue,scale=1){const w=Math.max(164,label.length*23+48);return `<g transform="translate(${x} ${y}) scale(${scale})">${rect(-w/2,-35,w,70,C.navy,10,`stroke="${color}" stroke-width="2.5"`)}${mt(0,9,label,28,color,'text-anchor="middle"')}</g>`;}
export function lock(x:number,y:number,p:number){return `<g transform="translate(${x} ${y}) scale(${Math.max(.001,p)})">${rect(-22,-4,44,36,C.cyan,7)}<path d="M-13-4V-17a13 13 0 0126 0V-4" fill="none" stroke="${C.cyan}" stroke-width="5"/>${dot(0,10,3,C.navy)}</g>`;}
export function chrome(t:number,content:string){const labels=['CLICK','URL','DNS','CONNECT','REQUEST','RESPONSE','RENDER'];const p=progress(t,0,27);return `${mt(104,78,'WHAT HAPPENS WHEN YOU CLICK A LINK?',22,C.white)}${mt(1816,78,'A WEB FIELD GUIDE / 001',20,C.slate,'text-anchor="end"')}${line(104,107,1816,107,C.slate,1,'opacity=".25"')}${content}${line(104,956,1816,956,C.slate,1,'opacity=".25"')}${mt(104,1010,'SIMPLIFIED HTTPS NAVIGATION',20,C.slate)}${labels.map((s,i)=>mt(850+i*143,1010,s,17, p*7>i?C.cyan:C.slate,'text-anchor="middle"')).join('')}`;}
export function networkTexture(){return `<g opacity=".28">${Array.from({length:14},(_,i)=>line(100+i*132,135,100+i*132,930,C.mid,1)).join('')}${Array.from({length:7},(_,i)=>line(85,150+i*128,1835,150+i*128,C.mid,1)).join('')}</g>`;}
export const span=(a:number,b:number,p:number)=>lerp(a,b,clamp(p));
