export function finaleScene(t:number){const flatten=E(t,.05,.75),title=E(t,.4,1.0);const labels=['CLICK','URL','DNS','TLS','HTTP','HTML','PAGE'];const net=labels.map((s,i)=>{const x=220+i*245,y=lerp(560+(i%2?90:-40),580,flatten);return `${i<6?line(x,y,x+245,lerp(560+((i+1)%2?90:-40),580,flatten),C.cyan,2):''}${rect(x-59,y-26,118,52,C.mid,7,`opacity="${1-flatten}"`)}${mt(x,y+7,s,22,C.white,`text-anchor="middle" opacity="${1-flatten}"`)}${dot(x,y,4,C.cyan)}`;}).join('');const shrink=E(t,0,.5);const page=browser(860,400,845,445,`${rect(892,484,780,323,C.navy,8)}${mt(924,537,'EXAMPLE / FIELD NOTES',17,C.cyan)}${tx(921,606,'A world connected.',43)}${line(925,647,1261,647,C.slate,8,'opacity=".45"')}${line(925,672,1223,672,C.slate,8,'opacity=".25"')}${rect(925,715,205,51,C.blue,7)}${mt(946,749,'EXPLORE →',20,C.white)}${rect(1330,520,275,245,C.mid,10)}${dot(1473,621,65,C.cyan)}${line(1378,708,1559,573,C.blue,22)}${dot(1415,591,24,C.amber)}`);return `<g opacity="${1-shrink}" transform="translate(${960*(1-lerp(1,.1,shrink))} ${580*(1-lerp(1,.1,shrink))}) scale(${lerp(1,.1,shrink)})">${page}</g><g opacity="${(1-title)*shrink}">${net}</g>${line(lerp(220,104,title),580,lerp(1690,1816,title),580,C.cyan,2,`opacity="${1-E(t,.6,1.1)}"`)}${appear(mt(108,297,'ONE CLICK. A WHOLE JOURNEY.',24,C.cyan),t,.25)}${appear(tx(98,459,'ALL THAT.',124,C.white,'letter-spacing="-6"'),t,.55,55)}${appear(tx(98,594,'FROM ONE CLICK.',124,C.white,'letter-spacing="-6"'),t,.68,55)}${appear(line(108,670,1812,670,C.slate,1,'opacity=".35"')+mt(108,739,'THE WEB, EXPLAINED THROUGH MOTION.',29,C.cyan),t,.95)}${appear(mt(108,866,'DNS → CONNECTION → REQUEST → RESPONSE → RENDER',23,C.slate),t,1.05)}`;}
