export function dnsScene(t:number){const query=E(t,.55,1.2),answer=E(t,2.1,2.75),exit=E(t,3.4,4),intro=E(t,0,.5);
 const directory=panel(1130,415,500,340,`${mt(1166,466,'DNS RESOLVER',24,C.white)}${line(1165,494,1594,494,C.slate,1,'opacity=".3"')}${[0,1,2].map(i=>`${rect(1165,522+i*64,430,48,i===1?C.navy:C.mid,6,i===1?`stroke="${C.cyan}" stroke-width="1"`:'')}${line(1183,546+i*64,1200,546+i*64,i===1?C.cyan:C.slate,3)}${mt(1220,553+i*64,['cached entries','example.com','upstream lookup'][i],21,i===1?C.cyan:C.slate)}`).join('')}`,C.cyan);
 return `${heading(t,3,'DNS LOOKUP','Finding an address. Not fetching a webpage.')}<g opacity="${1-exit}">${appear(directory,t,.2)}${line(430,570,1129,570,C.slate,2,'opacity=".4"')}${line(1129,695,430,695,C.cyan,2,`opacity="${S(t,2.05)}" marker-end="url(#arrowCyan)"`)}<g opacity="${1-E(t,1.15,1.4)}">${message(lerp(960,lerp(555,1040,query),intro),lerp(609,570,intro),'example.com',C.cyan,lerp(1,.75,query))}</g>${appear(message(lerp(1230,630,answer),695,'203.0.113.10',C.amber,.88),t,2.05)}${mt(1135,809,'CACHES / UPSTREAM RESOLVERS',19,C.slate)}${mt(105,881,'CACHE MAY SKIP THIS STEP',22,C.slate)}</g><g opacity="${exit}">${dot(1540,650,20,C.amber)}${tx(1540,787,'203.0.113.10',26,C.amber,'text-anchor="middle" font-family="\'IBM Plex Mono\'"')}</g>${appear(mt(105,820,'example.com → 203.0.113.10',31,C.white),t,2.55)}`;
}
