import {C,appear,line,mt,word} from '../lib/design';
import {E,clamp,fastVelocity,fastX,lerp} from '../lib/motion';
export function fast(t:number){const x=fastX(t),v=fastVelocity(t),stretch=1+Math.min(.14,Math.abs(v)/40000),brake=E(t,10.25,11);const w=640;const ghosts=[3,2,1].map(i=>`<g opacity="${Math.min(.075,Math.abs(v)/80000)*(1-brake)}">${word('FAST',x-w/2-Math.sign(v)*i*Math.min(28,Math.abs(v)/200),1010,w,C.ink)}</g>`).join('');return `${appear(mt(100,401,'BLINK. YOU MISSED IT.',25),t,8.18)}${[0,1,2].map(i=>line(100,820+i*130,960,820+i*130,C.ink,1,'opacity=".16"')).join('')}${[0,1,2,3].map(i=>line(clamp(x-600-i*75,-500,1080),910+i*32,clamp(x-430-i*50,-300,1080),910+i*32,C.ivory,3,`opacity="${Math.min(.8,Math.abs(v)/5000)*(1-brake)}"`)).join('')}<g transform="translate(${x} 1000) skewX(-9) scale(${stretch} ${1/stretch}) translate(${-x} -1000)" opacity="${1-brake}">${ghosts}${word('FAST',x-w/2,1010,w,C.ink)}</g>${line(100,1110,lerp(100,950,E(t,10.15,11)),1110,C.ink,2)}${mt(100,1355,'ACCELERATE → OVERSHOOT → BRAKE',21)}`;}
