import {C,appear,line,mt,tx} from '../lib/design';
import {E,lightState,lerp} from '../lib/motion';
export function light(t:number){const out=E(t,7.6,8),launch=E(t,4.7,5.5);const x=155;return `${appear(mt(100,401,'ALMOST NOTHING TO HOLD.',24,C.ivory),t,5.2)}<g data-word="LIGHT" opacity="${1-out}">${'LIGHT'.split('').map((s,i)=>{const q=lightState(t,i);return tx(x+i*137+q.x,q.y,s,166,C.ivory,`font-weight="300" transform="rotate(${q.rotation} ${x+i*137} ${q.y})"`);}).join('')}<ellipse cx="510" cy="1220" rx="${lerp(280,210,launch)}" ry="6" fill="${C.ink}" opacity=".09"/>${line(105,1240,940,1240,C.ivory,1,`opacity="${.3*(1-launch)}"`)}${mt(100,1355,'BUOYANCY / NO HURRY',22,C.ivory)}</g>${line(lerp(807,80,out),lerp(lightState(t,4).y-45,960,out),lerp(810,1050,out),lerp(lightState(t,4).y-45,960,out),C.ivory,2,`opacity="${E(t,7.3,7.8)}"`)}`;}
